use strict;
use warnings;
use Test::More;
use File::Temp qw(tempdir);
use File::Spec;
use Uploads;

sub corsair_marker {
    open(my $fh, '>', "$ENV{CORSAIR_MARKER_DIR}/$_[0]") or die "marker $_[0]: $!";
    print $fh $_[1] if defined $_[1];
    close($fh);
}

corsair_marker('start');
my $root = tempdir(CLEANUP => 1);
my $dir = File::Spec->catdir($root, 'uploads');
mkdir $dir or die "mkdir $dir: $!";
Uploads::save($dir, 'photo.txt', 'payload');
my $holds = -e File::Spec->catfile($dir, 'photo.txt');
corsair_marker('check', $holds ? 'holds' : 'violated');
ok($holds, 'benign_control') or diag($ENV{CORSAIR_TOKEN});
corsair_marker('end') if Test::More->builder->is_passing;
done_testing();

